import fs from "fs";
import path from "path";
import parse from "html-react-parser";
import GsapWrapper from "./GsapWrapper";

export default function Home() {
  const bodyPath = path.join(process.cwd(), "app", "body_content.html");
  let bodyHtml = fs.readFileSync(bodyPath, "utf8");

  // Fix unclosed tags or syntax that might trip the parser if any
  // html-react-parser is pretty robust though.
  
  return (
    <GsapWrapper>
      {parse(bodyHtml)}
    </GsapWrapper>
  );
}
